import math
from fractions import Fraction
from typing import List


def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """ Check if in given list of numbers, are any two numbers closer to each other than
    given threshold.
    >>> has_close_elements([1.0, 2.0, 3.0], 0.5)
    False
    >>> has_close_elements([1.0, 2.8, 3.0, 4.0, 5.0, 2.0], 0.3)
    True
    """
    values = list(numbers)
    if len(values) < 2:
        return False

    if all(math.isfinite(x) for x in values) and math.isfinite(threshold):
        limit = Fraction(threshold)
        exact = sorted(Fraction(x) for x in values)
        return any(b - a < limit for a, b in zip(exact, exact[1:]))

    for i in range(len(values)):
        for j in range(i + 1, len(values)):
            if abs(values[i] - values[j]) < threshold:
                return True
    return False

