import unicodedata


def _hangul_type(cp):
    if 0x1100 <= cp <= 0x115F or 0xA960 <= cp <= 0xA97C:
        return 'L'
    if 0x1160 <= cp <= 0x11A7 or 0xD7B0 <= cp <= 0xD7C6:
        return 'V'
    if 0x11A8 <= cp <= 0x11FF or 0xD7CB <= cp <= 0xD7FB:
        return 'T'
    if 0xAC00 <= cp <= 0xD7A3:
        return 'LV' if (cp - 0xAC00) % 28 == 0 else 'LVT'
    return None


def _char_type(ch):
    cp = ord(ch)
    if ch == '\r':
        return 'CR'
    if ch == '\n':
        return 'LF'
    if cp == 0x200D:
        return 'ZWJ'
    if cp == 0x200C or 0x1F3FB <= cp <= 0x1F3FF or 0xE0020 <= cp <= 0xE007F:
        return 'Extend'
    if 0x1F1E6 <= cp <= 0x1F1FF:
        return 'RI'
    category = unicodedata.category(ch)
    if category in ('Mn', 'Me'):
        return 'Extend'
    if category == 'Mc':
        return 'SpacingMark'
    if category in ('Cc', 'Zl', 'Zp') or (category == 'Cf' and cp not in (0x200C, 0x200D)):
        return 'Control'
    hangul = _hangul_type(cp)
    if hangul:
        return hangul
    return 'Other'


def _is_boundary(prev, curr, ri_count):
    if prev == 'CR' and curr == 'LF':
        return False
    if prev in ('CR', 'LF', 'Control') or curr in ('CR', 'LF', 'Control'):
        return True
    if prev == 'L' and curr in ('L', 'V', 'LV', 'LVT'):
        return False
    if prev in ('LV', 'V') and curr in ('V', 'T'):
        return False
    if prev in ('LVT', 'T') and curr == 'T':
        return False
    if curr in ('Extend', 'ZWJ', 'SpacingMark'):
        return False
    if prev == 'ZWJ':
        return False
    if prev == 'RI' and curr == 'RI':
        return ri_count % 2 == 0
    return True


def _grapheme_count(string):
    count = 0
    prev = None
    ri_count = 0
    for ch in string:
        curr = _char_type(ch)
        if prev is None or _is_boundary(prev, curr, ri_count):
            count += 1
        if curr == 'RI':
            ri_count += 1
        else:
            ri_count = 0
        prev = curr
    return count


def prime_length(string):
    length = _grapheme_count(string)
    if length < 2:
        return False
    i = 2
    while i * i <= length:
        if length % i == 0:
            return False
        i += 1
    return True

