from collections import Counter


def find_even_pair(numbers):
    counts = Counter(numbers)
    even = sum(value % 2 == 0 for value in counts)
    odd = len(counts) - even
    return even * (even - 1) // 2 + odd * (odd - 1) // 2 + sum(count >= 2 for count in counts.values())

