import unicodedata


def sample_nam(names):
    def is_pictographic(char):
        value = ord(char)
        return (
            0x1F000 <= value <= 0x1FAFF
            or 0x2600 <= value <= 0x27BF
            or value in {
                0x00A9, 0x00AE, 0x203C, 0x2049, 0x2122, 0x2139,
                0x3030, 0x303D, 0x3297, 0x3299,
            }
        )

    def kind(char):
        value = ord(char)
        if char == '\r':
            return 'CR'
        if char == '\n':
            return 'LF'
        if char == '\u200d':
            return 'ZWJ'
        if 0x1F1E6 <= value <= 0x1F1FF:
            return 'RI'
        if 0x1100 <= value <= 0x115F or 0xA960 <= value <= 0xA97C:
            return 'L'
        if 0x1160 <= value <= 0x11A7 or 0xD7B0 <= value <= 0xD7C6:
            return 'V'
        if 0x11A8 <= value <= 0x11FF or 0xD7CB <= value <= 0xD7FB:
            return 'T'
        if 0xAC00 <= value <= 0xD7A3:
            return 'LVT' if (value - 0xAC00) % 28 else 'LV'
        if (
            0x0600 <= value <= 0x0605
            or value in {0x06DD, 0x070F, 0x0890, 0x0891, 0x08E2,
                         0x0D4E, 0x110BD, 0x110CD, 0x1193F,
                         0x11941, 0x11A3A, 0x11D46, 0x11F02}
            or 0x111C2 <= value <= 0x111C3
            or 0x11A84 <= value <= 0x11A89
        ):
            return 'Prepend'
        category = unicodedata.category(char)
        if (
            category.startswith('M')
            or char == '\u200c'
            or 0x1F3FB <= value <= 0x1F3FF
            or 0xE0020 <= value <= 0xE007F
        ):
            return 'Extend'
        if category in {'Cc', 'Cf', 'Zl', 'Zp', 'Cs'}:
            return 'Control'
        return 'Other'

    def grapheme_length(name):
        count = 0
        previous = None
        regional_run = 0
        last_base_is_picture = False
        picture_before_zwj = False
        controls = {'CR', 'LF', 'Control'}

        for char in name:
            current = kind(char)
            if previous is None:
                joined = False
            elif previous == 'CR' and current == 'LF':
                joined = True
            elif previous in controls or current in controls:
                joined = False
            else:
                joined = (
                    current in {'Extend', 'ZWJ'}
                    or previous == 'Prepend'
                    or (previous == 'L' and current in {'L', 'V', 'LV', 'LVT'})
                    or (previous in {'LV', 'V'} and current in {'V', 'T'})
                    or (previous in {'LVT', 'T'} and current == 'T')
                    or (previous == 'RI' and current == 'RI' and regional_run % 2 == 1)
                    or (previous == 'ZWJ' and picture_before_zwj and is_pictographic(char))
                )
            if not joined:
                count += 1
            if current == 'ZWJ':
                picture_before_zwj = last_base_is_picture
            elif current != 'Extend':
                last_base_is_picture = is_pictographic(char)
                picture_before_zwj = False
            regional_run = regional_run + 1 if current == 'RI' else 0
            previous = current
        return count

    return sum(grapheme_length(name) for name in names if not name[:1].islower())

