def do_algebra(operator, operand):
    precedence = {'+': 1, '-': 1, '*': 2, '//': 2, '**': 3}
    values = [operand[0]]
    operators = []

    def apply():
        op = operators.pop()
        right = values.pop()
        left = values.pop()
        if op == '+':
            result = left + right
        elif op == '-':
            result = left - right
        elif op == '*':
            result = left * right
        elif op == '//':
            result = left // right
        else:
            result = left ** right
        values.append(result)

    for op, value in zip(operator, operand[1:]):
        while operators and precedence[operators[-1]] >= precedence[op]:
            apply()
        operators.append(op)
        values.append(value)

    while operators:
        apply()

    return values[0]

def do_algebra(operator, operand):
    powered_values = [operand[0]]
    remaining_ops = []
    for op, value in zip(operator, operand[1:]):
        if op == '**':
            powered_values[-1] = powered_values[-1] ** value
        else:
            remaining_ops.append(op)
            powered_values.append(value)

    terms = [powered_values[0]]
    additive_ops = []
    for op, value in zip(remaining_ops, powered_values[1:]):
        if op == '*':
            terms[-1] = terms[-1] * value
        elif op == '//':
            terms[-1] = terms[-1] // value
        elif op in ('+', '-'):
            additive_ops.append(op)
            terms.append(value)
        else:
            raise ValueError('Unsupported operator: ' + str(op))

    result = terms[0]
    for op, value in zip(additive_ops, terms[1:]):
        if op == '+':
            result += value
        else:
            result -= value
    return result

