        (0x2122, 0x2122), (0x2139, 0x2139), (0x2194, 0x2199), (0x21A9, 0x21AA),
        (0x231A, 0x231B), (0x2328, 0x2328), (0x2388, 0x2388), (0x23CF, 0x23CF),
        (0x23E9, 0x23F3), (0x23F8, 0x23FA), (0x24C2, 0x24C2), (0x25AA, 0x25AB),
        (0x25B6, 0x25B6), (0x25C0, 0x25C0), (0x25FB, 0x25FE), (0x2600, 0x27BF),
        (0x2934, 0x2935), (0x2B05, 0x2B07), (0x2B1B, 0x2B1C), (0x2B50, 0x2B50),
        (0x2B55, 0x2B55), (0x3030, 0x3030), (0x303D, 0x303D), (0x3297, 0x3297),
        (0x3299, 0x3299), (0x1F000, 0x1F1E5), (0x1F200, 0x1F3FA),
        (0x1F400, 0x1FAFF), (0x1FC00, 0x1FFFD),
    )
    prepend = {0x06DD, 0x070F, 0x0890, 0x0891, 0x08E2, 0x0D4E, 0x110BD, 0x110CD,
               0x111C2, 0x111C3}

    def classify(ch):
        cp = ord(ch)
        if cp == 0x0D:
            return 'CR'
        if cp == 0x0A:
            return 'LF'
        if cp == 0x200D:
            return 'ZWJ'
        if cp == 0x200C or 0x1F3FB <= cp <= 0x1F3FF or 0xE0020 <= cp <= 0xE007F:
            return 'Extend'
        if 0x1F1E6 <= cp <= 0x1F1FF:
            return 'RI'
        if 0x0600 <= cp <= 0x0605 or cp in prepend:
            return 'Prepend'
        if 0x1100 <= cp <= 0x115F or 0xA960 <= cp <= 0xA97C:
            return 'L'
        if 0x1160 <= cp <= 0x11A7 or 0xD7B0 <= cp <= 0xD7C6:
            return 'V'
        if 0x11A8 <= cp <= 0x11FF or 0xD7CB <= cp <= 0xD7FB:
            return 'T'
        if 0xAC00 <= cp <= 0xD7A3:
            return 'LV' if (cp - 0xAC00) % 28 == 0 else 'LVT'
        category = unicodedata.category(ch)
        if category in ('Mn', 'Me'):
            return 'Extend'
        if category == 'Mc':
            return 'SpacingMark'
        if category in ('Cc', 'Cf', 'Zl', 'Zp'):
            return 'Control'
        for low, high in pictographic_ranges:
            if low <= cp <= high:
                return 'Pict'
        return 'Other'

    def is_break(prev, cur, ri_run, pict_state):
        if prev == 'CR' and cur == 'LF':
            return False
        if prev in ('CR', 'LF', 'Control') or cur in ('CR', 'LF', 'Control'):
            return True
        if prev == 'L' and cur in ('L', 'V', 'LV', 'LVT'):
            return False
        if prev in ('LV', 'V') and cur in ('V', 'T'):
            return False
        if prev in ('LVT', 'T') and cur == 'T':
            return False
        if cur in ('Extend', 'ZWJ', 'SpacingMark'):
            return False
        if prev == 'Prepend':
            return False
        if prev == 'ZWJ' and cur == 'Pict' and pict_state == 2:
            return False
        if prev == 'RI' and cur == 'RI' and ri_run % 2 == 1:
            return False
        return True

    count = 0
    prev = None
    ri_run = 0
    pict_state = 0
    for ch in string:
        cur = classify(ch)
        if prev is None or is_break(prev, cur, ri_run, pict_state):
            count += 1
        if cur == 'RI':
            ri_run = ri_run + 1 if prev == 'RI' else 1
        else:
            ri_run = 0
        if cur == 'Pict':
            pict_state = 1
        elif cur == 'Extend' and pict_state == 1:
            pict_state = 1
        elif cur == 'ZWJ' and pict_state == 1:
            pict_state = 2
        else:
            pict_state = 0
        prev = cur
    return count

