def poly(xs: list, x: float):
    return sum([coeff * math.pow(x, i) for i, coeff in enumerate(xs)])


def _is_near_zero(cs, x):
    scale = sum(abs(c) * abs(x) ** i for i, c in enumerate(cs))
    return abs(poly(cs, x)) <= 1e-9 * max(scale, 1e-300)


def _bisect(cs, a, b):
    fa = poly(cs, a)
    for _ in range(300):
        m = (a + b) / 2.0
        if m == a or m == b:
            break
        fm = poly(cs, m)
        if fm == 0:
            return m
        if (fa < 0) == (fm < 0):
            a, fa = m, fm
        else:
            b = m
    return (a + b) / 2.0


def _real_roots(xs):
    cs = [float(c) for c in xs]
    while len(cs) > 1 and cs[-1] == 0:
        cs.pop()
    n = len(cs) - 1
    if n <= 0:
        return []
    if n == 1:
        return [-cs[0] / cs[1]]
    bound = 1.0 + max(abs(c / cs[-1]) for c in cs[:-1])
    derivative = [i * c for i, c in enumerate(cs)][1:]
    critical = sorted(p for p in _real_roots(derivative) if -bound < p < bound)
    points = [-bound] + critical + [bound]
    roots = [p for p in critical if _is_near_zero(cs, p)]
    for a, b in zip(points, points[1:]):
        fa, fb = poly(cs, a), poly(cs, b)
        if fa == 0 or fb == 0:
            continue
        if (fa < 0) != (fb < 0):
            roots.append(_bisect(cs, a, b))
    roots.sort()
    distinct = []
    for r in roots:
        if not distinct or abs(r - distinct[-1]) > 1e-7 * max(1.0, abs(r)):
            distinct.append(r)
    return distinct


