def find_zero(xs: list):
    if xs[0] == 0:
        return 0.0

    left, right = -1.0, 1.0
    while True:
        left_value = poly(xs, left)
        right_value = poly(xs, right)
        if left_value == 0:
            return left
        if right_value == 0:
            return right
        if (left_value < 0) != (right_value < 0):
            break
        left *= 2.0
        right *= 2.0

    while True:
        middle = left / 2.0 + right / 2.0
        if middle == left or middle == right:
            return middle
        middle_value = poly(xs, middle)
        if middle_value == 0:
            return middle
        if (middle_value < 0) == (left_value < 0):
            left = middle
            left_value = middle_value
        else:
            right = middle

