def find_zero(xs: list):
    def evaluate(coefficients, x):
        value = Fraction(0)
        for coefficient in reversed(coefficients):
            value = value * x + coefficient
        return value

    def divide(dividend, divisor):
        remainder = dividend[:]
        quotient = [Fraction(0)] * max(0, len(dividend) - len(divisor) + 1)
        while remainder and len(remainder) >= len(divisor):
            offset = len(remainder) - len(divisor)
            factor = remainder[-1] / divisor[-1]
            quotient[offset] = factor
            for i, coefficient in enumerate(divisor):
                remainder[offset + i] -= factor * coefficient
            while remainder and remainder[-1] == 0:
                remainder.pop()
        return quotient, remainder

    def sturm_sequence(coefficients):
        derivative = [i * coefficients[i] for i in range(1, len(coefficients))]
        sequence = [coefficients, derivative]
        while sequence[-1]:
            _, remainder = divide(sequence[-2], sequence[-1])
            if not remainder:
                break
            scale = abs(remainder[-1])
            sequence.append([-coefficient / scale for coefficient in remainder])
        return sequence

    coefficients = [Fraction(coefficient) for coefficient in xs]
    while coefficients and coefficients[-1] == 0:
        coefficients.pop()
    if not coefficients:
        return 0.0
    if len(coefficients) == 1:
        raise ValueError('The polynomial has no real root')
    if len(coefficients) == 2:
        return float(-coefficients[0] / coefficients[1])

    sequence = sturm_sequence(coefficients)
    if len(sequence[-1]) > 1:
        coefficients, _ = divide(coefficients, sequence[-1])
        if len(coefficients) == 2:
            return float(-coefficients[0] / coefficients[1])
        sequence = sturm_sequence(coefficients)

    def variations(x):
        previous = 0
        changes = 0
        for polynomial in sequence:
            value = evaluate(polynomial, x)
            sign = (value > 0) - (value < 0)
            if sign:
                if previous and sign != previous:
                    changes += 1
                previous = sign
        return changes

    bound = 1 + max(abs(c / coefficients[-1]) for c in coefficients[:-1])
    left, right = -bound, bound
    left_variations = variations(left)

    while True:
        middle = (left + right) / 2
        result = float(middle)
        if result == float(left) or result == float(right):
            return result
        middle_variations = variations(middle)
        count = left_variations - middle_variations
        if count:
            if count == 1 and evaluate(coefficients, middle) == 0:
                return result
            right = middle
        else:
            left = middle
            left_variations = middle_variations

