def triangle_area(a, b, c):
    if a + b <= c or a + c <= b or b + c <= a:
        return -1
    with localcontext() as ctx:
        ctx.prec = 60
        da, db, dc = Decimal(str(a)), Decimal(str(b)), Decimal(str(c))
        s = (da + db + dc) / 2
        product = s * (s - da) * (s - db) * (s - dc)
        if product <= 0:
            return -1
        area = product.sqrt()
        return float(area.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

