from math import gcd


def _extended_gcd(a, b):
    old_r, r = a, b
    old_s, s = 1, 0
    old_t, t = 0, 1
    while r != 0:
        q = old_r // r
        old_r, r = r, old_r - q * r
        old_s, s = s, old_s - q * s
        old_t, t = t, old_t - q * t
    if old_r < 0:
        old_r, old_s, old_t = -old_r, -old_s, -old_t
    return old_r, old_s, old_t


def find_solution(a, b, n):
    g = gcd(a, b)
    if g == 0:
        return (0, 0) if n == 0 else None
    if n % g != 0:
        return None

    if a > 0 and b > 0 and n > 0:
        best = None
        for x in range(n // a + 1):
            rest = n - a * x
            if rest % b == 0:
                y = rest // b
                key = (abs(x - y), x)
                if best is None or key < best[0]:
                    best = (key, (x, y))
        if best is not None:
            return best[1]

    _, s, t = _extended_gcd(a, b)
    factor = n // g
    return (s * factor, t * factor)

def find_solution(a, b, n):
    def ext_gcd(p, q):
        if q == 0:
            return (p, 1, 0) if p >= 0 else (-p, -1, 0)
        g, s, t = ext_gcd(q, p % q)
        return g, t, s - (p // q) * t

    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if b == 0:
        return (n // a, 0) if n % a == 0 else None
    if a == 0:
        return (0, n // b) if n % b == 0 else None

    g, s, t = ext_gcd(a, b)
    if n % g != 0:
        return None

    step = abs(b // g)
    x = (s * (n // g)) % step
    y = (n - a * x) // b
    return (x, y)

def find_solution(a, b, n):
    if a == 0:
        if b == 0:
            return (0, 0) if n == 0 else None
        return (0, n // b) if n % b == 0 else None
    if b == 0:
        return (n // a, 0) if n % a == 0 else None

    old_r, r = abs(a), abs(b)
    old_s, s = 1, 0
    while r:
        quotient = old_r // r
        old_r, r = r, old_r - quotient * r
        old_s, s = s, old_s - quotient * s

    if n % old_r:
        return None

    x = old_s * (n // old_r) * (1 if a > 0 else -1)
    y = (n - a * x) // b

    if a > 0 and b > 0 and n > 0:
        step_x = b // old_r
        step_y = a // old_r
        lower = -(x // step_x)
        upper = y // step_y
        if lower <= upper:
            center = (y - x) // (step_x + step_y)
            candidates = {
                max(lower, min(upper, center)),
                max(lower, min(upper, center + 1)),
            }
            pairs = [(x + k * step_x, y - k * step_y) for k in candidates]
            return min(pairs, key=lambda pair: (abs(pair[0] - pair[1]), pair[0]))

    return x, y

