def is_woodall(number):
    if not isinstance(number, int) or number < 1:
        return False
    target = number + 1
    n = 1
    power = 2
    while n * power < target:
        n += 1
        power <<= 1
    return n * power == target

def count_Set_Bits(n):
    if n < 0:
        width = (~n).bit_length() + 1
        n &= (1 << width) - 1
    return bin(n).count('1')

def count_Set_Bits(n):
