def even_bit_set_number(n):
    if n >= 0:
        width = n.bit_length()
    else:
        width = n.bit_length() + 2
    mask = 0
    for position in range(1, width, 2):
        mask |= 1 << position
    return n | mask

def even_bit_set_number(n):
    if n < 0:
        return -even_bit_set_number(-n)
    mask = 0
    position = 1
    length = n.bit_length()
    while position < length:
        mask |= 1 << position
        position += 2
    return n | mask

