def set_left_most_unset_bit(n):
    if n == 0:
        return 1
    if n & (n + 1) == 0:
        return n
    pos = n.bit_length() - 1
    while pos >= 0:
        if not (n >> pos) & 1:
            return n | (1 << pos)
        pos -= 1
    return n

def set_left_most_unset_bit(n):
    if n == 0:
        return 0
    if n & (n + 1) == 0:
        return n
    pos = 0
    temp = n
    count = 0
    while temp:
        if not temp & 1:
            pos = count
        count += 1
        temp >>= 1
    return n | (1 << pos)

