def _is_pictographic(cp):
    for lo, hi in _PICTOGRAPHIC_RANGES:
        if lo <= cp <= hi:
            return True
    return False


def _property(ch):
    cp = ord(ch)
    if cp == 0x0D:
        return 'CR'
    if cp == 0x0A:
        return 'LF'
    if cp == 0x200D:
        return 'ZWJ'
    if 0x1F1E6 <= cp <= 0x1F1FF:
        return 'RI'
    if (cp == 0x200C or 0x1F3FB <= cp <= 0x1F3FF or 0xE0020 <= cp <= 0xE007F
            or 0xFF9E <= cp <= 0xFF9F):
        return 'Extend'
    if 0x0600 <= cp <= 0x0605 or 0x0890 <= cp <= 0x0891 or cp in _PREPEND:
        return 'Prepend'
    if 0x1100 <= cp <= 0x115F or 0xA960 <= cp <= 0xA97C:
        return 'L'
    if 0x1160 <= cp <= 0x11A7 or 0xD7B0 <= cp <= 0xD7C6:
        return 'V'
    if 0x11A8 <= cp <= 0x11FF or 0xD7CB <= cp <= 0xD7FB:
        return 'T'
    if 0xAC00 <= cp <= 0xD7A3:
        return 'LV' if (cp - 0xAC00) % 28 == 0 else 'LVT'
    category = unicodedata.category(ch)
    if category in ('Mn', 'Me'):
        return 'Extend'
    if category == 'Mc':
        return 'SpacingMark'
    if category in ('Cc', 'Cf', 'Zl', 'Zp', 'Cs'):
        return 'Control'
    if _is_pictographic(cp):
        return 'ExtPict'
    return 'Other'


def _should_break(prev, cur, ri_run, pict_state):
    if prev == 'CR' and cur == 'LF':
        return False
    if prev in ('Control', 'CR', 'LF'):
        return True
    if cur in ('Control', 'CR', 'LF'):
        return True
    if prev == 'L' and cur in ('L', 'V', 'LV', 'LVT'):
        return False
    if prev in ('LV', 'V') and cur in ('V', 'T'):
        return False
    if prev in ('LVT', 'T') and cur == 'T':
        return False
    if cur in ('Extend', 'ZWJ', 'SpacingMark'):
        return False
    if prev == 'Prepend':
        return False
    if prev == 'ZWJ' and cur == 'ExtPict' and pict_state == 2:
        return False
    if prev == 'RI' and cur == 'RI':
        return ri_run % 2 == 0
    return True


def split(word):
    clusters = []
    current = ''
    prev = None
    ri_run = 0
    pict_state = 0
    for ch in word:
        cur = _property(ch)
        if prev is not None and _should_break(prev, cur, ri_run, pict_state):
            clusters.append(current)
            current = ch
        else:
            current += ch
        if cur == 'RI':
            ri_run = ri_run + 1 if prev == 'RI' else 1
        else:
            ri_run = 0
        if cur == 'ExtPict':
            pict_state = 1
        elif cur == 'Extend' and pict_state == 1:
            pict_state = 1
        elif cur == 'ZWJ' and pict_state == 1:
            pict_state = 2
        else:
            pict_state = 0
        prev = cur
    if current:
        clusters.append(current)
    return clusters

