def comb_sort(nums):
    items = list(nums)

    def key(x):
        return x.lower() if isinstance(x, str) else x

    gap = len(items)
    shrink = 1.3
    swapped = True
    while gap > 1 or swapped:
        gap = max(1, int(gap / shrink))
        swapped = False
        for i in range(len(items) - gap):
            if key(items[i]) > key(items[i + gap]):
                items[i], items[i + gap] = items[i + gap], items[i]
                swapped = True
    return items

def comb_sort(nums):
    result = list(nums)
    n = len(result)
    gap = n
    shrink = 1.3
    swapped = True
    while gap > 1 or swapped:
        gap = int(gap / shrink)
        if gap < 1:
            gap = 1
        swapped = False
        for i in range(n - gap):
            if result[i] > result[i + gap]:
                result[i], result[i + gap] = result[i + gap], result[i]
                swapped = True
    return result

def comb_sort(elements):
    result = list(elements)
    gap = len(result)
    swapped = True

    while gap > 1 or swapped:
        gap = max(1, gap * 10 // 13)
        swapped = False
        for i in range(len(result) - gap):
            j = i + gap
            if result[i] > result[j]:
                result[i], result[j] = result[j], result[i]
                swapped = True

    return result

