import unicodedata


def _is_extend(cp):
    ch = chr(cp)
    cat = unicodedata.category(ch)
    if cat in ("Mn", "Me", "Mc"):
        return True
    if cp in (0x200C, 0x200D):
        return True
    if 0xFE00 <= cp <= 0xFE0F or 0xE0100 <= cp <= 0xE01EF:
        return True
    if 0x1F3FB <= cp <= 0x1F3FF:
        return True
    if 0xE0020 <= cp <= 0xE007F:
        return True
    return False


def _is_control(cp):
    if cp in (0x200C, 0x200D):
        return False
    if 0xE0020 <= cp <= 0xE007F:
        return False
    cat = unicodedata.category(chr(cp))
    return cat in ("Cc", "Zl", "Zp", "Cf")


def _is_pictographic(cp):
    return (
        cp in (0x00A9, 0x00AE, 0x203C, 0x2049, 0x2122, 0x2139, 0x3030, 0x303D, 0x3297, 0x3299)
        or 0x2190 <= cp <= 0x21FF
        or 0x2300 <= cp <= 0x23FF
        or 0x25A0 <= cp <= 0x27BF
        or 0x2B00 <= cp <= 0x2BFF
        or (0x1F000 <= cp <= 0x1FAFF and not 0x1F1E6 <= cp <= 0x1F1FF and not 0x1F3FB <= cp <= 0x1F3FF)
    )


def _hangul_type(cp):
    if 0x1100 <= cp <= 0x115F or 0xA960 <= cp <= 0xA97C:
        return "L"
    if 0x1160 <= cp <= 0x11A7 or 0xD7B0 <= cp <= 0xD7C6:
        return "V"
    if 0x11A8 <= cp <= 0x11FF or 0xD7CB <= cp <= 0xD7FB:
        return "T"
    if 0xAC00 <= cp <= 0xD7A3:
        return "LV" if (cp - 0xAC00) % 28 == 0 else "LVT"
    return None


def _is_regional(cp):
    return 0x1F1E6 <= cp <= 0x1F1FF


def _grapheme_count(text):
    count = 0
    prev = None
    ri_run = 0
    pictographic_base = False
    for ch in text:
        cp = ord(ch)
        if prev is None:
            joined = False
        elif prev == 0x0D and cp == 0x0A:
            joined = True
        elif _is_control(prev) or _is_control(cp):
            joined = False
        else:
            hp = _hangul_type(prev)
            hc = _hangul_type(cp)
            if hp == "L" and hc in ("L", "V", "LV", "LVT"):
                joined = True
            elif hp in ("LV", "V") and hc in ("V", "T"):
                joined = True
            elif hp in ("LVT", "T") and hc == "T":
                joined = True
            elif _is_extend(cp):
                joined = True
            elif prev == 0x200D and pictographic_base and _is_pictographic(cp):
                joined = True
            elif _is_regional(prev) and _is_regional(cp) and ri_run % 2 == 1:
                joined = True
            else:
                joined = False
        if not joined:
            count += 1
            pictographic_base = _is_pictographic(cp)
        elif _is_pictographic(cp):
            pictographic_base = True
        ri_run = ri_run + 1 if _is_regional(cp) else 0
        prev = cp
    return count


