def decimal_to_binary(n):
    if n >= 0:
        return bin(n)[2:]
    width = (-n - 1).bit_length() + 1
    return format(n + (1 << width), '0{}b'.format(width))

def decimal_to_binary(number):
    if number < 0:
        width = (~number).bit_length() + 1
        number += 1 << width
    return format(number, 'b')

def decimal_to_binary(n):
    if n < 0:
        return '-' + decimal_to_binary(-n)
    if n == 0:
        return '0'
    digits = []
    while n > 0:
        digits.append(str(n % 2))
        n //= 2
    return ''.join(reversed(digits))

